/* No.012 */
(() => {
const TEX = {"front": "front.jpg", "back": "back.jpg", "glitter": "glitter.png"};
const CORE_H = {"b16": 1, "n": 220, "x0": -1, "x1": 1, "y0": 1, "y1": -1, "h": ""};
/* No.012 wine-red core with a silver glitter flower, set in a pale clear acrylic rim */
function buildL() {
  const grp = new THREE.Group();
  const C = .78;                // core radius
  const core = new THREE.Group();
  // core front: flower relief with sparkling silver glitter
  const fm = glitterMat(tex(TEX.front), loader.load(TEX.glitter));
  fm.roughness = .2; fm.metalness = .55; fm.envMapIntensity = 1.1;
  const baseFm = fm.onBeforeCompile;
  fm.onBeforeCompile = (sh) => { baseFm(sh); sh.fragmentShader = sh.fragmentShader.replace('totalEmissiveRadiance += acc * mk * 2.6;', 'totalEmissiveRadiance += acc * mk * 4.0;'); };
  const front = new THREE.Mesh(cloverRelief(CORE_H, .095 / C, .07 / C), fm);
  front.onBeforeRender = (r, s, cam) => { fm.userData.uMV.value.setFromMatrix4(new THREE.Matrix4().multiplyMatrices(cam.matrixWorldInverse, front.matrixWorld)); };
  core.add(front);
  // core back: red dome with two slots and a bridge (photo already mirrored)
  const CH = { cx: .06, cy: .03, ang: -1.46, w: .26, L: .74, d: .2, bridge: .62 };
  const dome = (x, y) => { const r = Math.min(1, Math.hypot(x, y)); return -.4 * Math.pow(1 - r * r, .7); };
  const slot = (x, y) => {
    const dx = x - CH.cx, dy = y - CH.cy, ca = Math.cos(CH.ang), sa = Math.sin(CH.ang);
    const u = dx * ca + dy * sa, v = -dx * sa + dy * ca, au = Math.abs(u), hw = CH.w / 2;
    if (au > CH.L) return 0;
    const ends = Math.min(1, (CH.L - au) / .06);
    const side = Math.min(1, Math.max(0, (hw - Math.abs(v)) / .02));
    return CH.d * ends * side * side * (3 - 2 * side);
  };
  const BZ = -.05 / C;
  const backZ = (x, y) => { const z = dome(x, y); return BZ + z + Math.min(slot(x, y), -z); };
  const backMat = photoMat(tex(TEX.back), { roughness: .2, clearcoat: 1, clearcoatRoughness: .05, side: THREE.DoubleSide });
  core.add(new THREE.Mesh(cap(1, 72, 240, backZ, -1, false), backMat));
  const hw = CH.w / 2 + .02, Hh = CH.d;
  const br = new THREE.Shape();
  br.moveTo(-hw, 0); br.lineTo(-hw, Hh); br.lineTo(hw, Hh); br.lineTo(hw, 0);
  br.lineTo(hw - .04, 0); br.lineTo(hw - .04, Hh * .35); br.quadraticCurveTo(0, Hh * .8, -hw + .04, Hh * .35); br.lineTo(-hw + .04, 0); br.closePath();
  const bg = new THREE.ExtrudeGeometry(br, { depth: CH.bridge, bevelEnabled: true, bevelThickness: .01, bevelSize: .01, bevelSegments: 3, curveSegments: 8 });
  bg.rotateX(-Math.PI / 2); bg.translate(0, -CH.bridge / 2, 0); bg.rotateZ(CH.ang - Math.PI / 2);
  bg.translate(CH.cx, CH.cy, BZ + dome(CH.cx, CH.cy) + CH.d);
  const bp = bg.attributes.position, buv = bg.attributes.uv;
  for (let i = 0; i < bp.count; i++) buv.setXY(i, bp.getX(i) / 2 + .5, bp.getY(i) / 2 + .5);
  core.add(new THREE.Mesh(bg, backMat));
  core.add(new THREE.Mesh(rim(1, .095 / C, BZ, 200), new THREE.MeshPhysicalMaterial({ color: 0x5a1a20, roughness: .3, clearcoat: .8 })));
  core.scale.set(C, C, C);
  grp.add(core);
  // clear acrylic rim around the core
  const clear = new THREE.MeshPhysicalMaterial({
    color: 0xeedd96, metalness: 0, roughness: .04, transmission: .82, thickness: .5, ior: 1.49,
    attenuationColor: new THREE.Color(0xe8d070), attenuationDistance: .35,
    clearcoat: 1, clearcoatRoughness: .02, envMapIntensity: 1.3, side: THREE.DoubleSide
  });
  const prof = [[C, .1], [.92, .1]];
  for (let i = 1; i <= 10; i++) { const a = i / 10 * Math.PI / 2; prof.push([.92 + .08 * Math.sin(a), .1 - .1 * (1 - Math.cos(a))]); }
  for (let i = 1; i <= 8; i++) { const a = i / 8 * Math.PI / 2; prof.push([1 - .1 * (1 - Math.cos(a)), -.08 * Math.sin(a)]); }
  prof.push([C, -.08]); prof.push([C, .1]);
  const lg = new THREE.LatheGeometry(prof.map(([r, z]) => new THREE.Vector2(r, z)), 180);
  lg.rotateX(Math.PI / 2);
  grp.add(new THREE.Mesh(lg, clear));
  return grp;
}
buildL.env = 'jewel';
viewer(document.getElementById('cv'), buildL, 'v');
})();
